<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, problem } from '../api'
import type { ApiProblem, Evaluation } from '../types'
import { categoryNames, query, sourceNames, stateNames } from '../workbench'
import AsyncState from '../components/AsyncState.vue'
import RunPicker from '../components/RunPicker.vue'
import CaseDetailPanel from '../components/CaseDetailPanel.vue'
const props = defineProps<{ badcases?: boolean }>()
const route = useRoute(), router = useRouter(), rows = ref<Evaluation[]>([]), total = ref(0), loading = ref(true), error = ref<ApiProblem | null>(null)
const run = computed(() => query(route.query.run_id) || query(route.query.run)), score = computed(() => query(route.query.score_set_id) || query(route.query.score_set)), caseId = computed(() => query(route.query.case_run_id) || query(route.query.case))
const page = computed(() => Number(route.query.page) || 1), category = ref<string[]>([]), conclusion = ref(''), manual = ref(''), issue = ref('')
let generation = 0
async function load() { const current = ++generation; loading.value = true; error.value = null; rows.value = []; category.value = query(route.query.category).split(',').filter(Boolean); conclusion.value = query(route.query.conclusion); manual.value = query(route.query.manual_tag); issue.value = query(route.query.issue); try { const read = props.badcases ? api.badcases : api.evaluations; const data = await read({ run_id: run.value || undefined, score_set_id: score.value || undefined, category: category.value.join(',') || undefined, conclusion: !props.badcases ? conclusion.value || undefined : undefined, manual_tag: props.badcases ? manual.value || undefined : undefined, issue: props.badcases ? issue.value || undefined : undefined, metric: query(route.query.metric) || undefined, case_run_ids: query(route.query.case_run_ids) || undefined, page: page.value }); if (current === generation) { rows.value = data.items; total.value = data.total } } catch (e) { if (current === generation) error.value = problem(e) } finally { if (current === generation) loading.value = false } }
function filter() { void router.replace({ query: { ...route.query, category: category.value.filter(Boolean).join(',') || undefined, conclusion: conclusion.value || undefined, manual_tag: manual.value || undefined, issue: issue.value || undefined, page: undefined } }) }
function pick(id: string, selected: string) { void router.replace({ query: { run_id: id || undefined, score_set_id: selected || undefined } }) }
function open(row: Evaluation) { void router.replace({ query: { ...route.query, case_run_id: row.id, score_set_id: score.value || undefined } }) }
function scoreChange(id: string) { void router.replace({ query: { ...route.query, score_set_id: id, score_set: undefined } }) }
watch(() => [route.fullPath, props.badcases], load, { immediate: true })
</script>
<template><div class="page-heading"><div><div class="eyebrow">{{ badcases ? 'BADCASES / HUMAN REVIEW' : 'EVALUATIONS / EXECUTION FACTS' }}</div><h1>{{ badcases ? 'Badcase 与人工复核' : '评测详情' }}</h1><p>{{ badcases ? '七类自动原因可同时出现；评分故障与缺失观测单列。' : '从冻结用例读取执行、轨迹与评分，逐项查看事实和依据。' }}</p></div><ElButton @click="load">刷新列表</ElButton></div><section class="panel"><div class="panel-body"><RunPicker :run-id="run" :score-set-id="score" allow-empty @change="pick" /><p v-if="route.query.case_run_ids || route.query.metric" class="small muted">来自报告钻取：{{ route.query.metric || '指定参与统计的用例集合' }}。<RouterLink class="text-link" :to="{ path: route.path, query: { run_id: run, score_set_id: score } }">清除钻取条件</RouterLink></p></div><form class="filter-row" @submit.prevent="filter"><label>自动分类（按住 Ctrl 可多选）<select v-model="category" multiple size="3" aria-label="自动分类多选"><option value="">全部分类</option><option v-for="(label, key) in categoryNames" :key="key" :value="key">{{ label }}</option></select></label><label v-if="!badcases">结论<select v-model="conclusion"><option value="">全部结论</option><option value="PASS">通过</option><option value="FAIL">失败</option><option value="UNDETERMINED">未判定</option></select></label><template v-else><label>人工原因<input v-model="manual" placeholder="按原因精确筛选" /></label><label>评测异常<select v-model="issue"><option value="">全部（含评分故障）</option><option value="JUDGE_ERROR">Judge 评分故障</option><option value="SCORING_PENDING">评分尚未完成</option><option value="NOT_EXECUTED">尚未执行</option><option value="REQUIRED_METRIC_ERROR">必评指标错误</option><option value="REQUIRED_METRIC_NA">必评证据不足</option><option value="FULL_CONTEXT_UNAVAILABLE">完整上下文不可用</option></select></label></template><ElButton native-type="submit" size="small">应用筛选</ElButton><span class="small muted">{{ total }} 条已保存记录</span></form><AsyncState :loading="loading" :error="error" :empty="!rows.length" :empty-title="badcases ? '没有符合筛选条件的 Badcase 或评测异常' : '没有符合条件的执行记录'" empty-text="可更换运行、评分集或筛选条件；尚未运行时请先创建实验。" @retry="load"><template #empty-action><RouterLink class="text-link" to="/experiments">前往实验</RouterLink></template><div class="table-scroll"><table><thead><tr><th>冻结用例</th><th>执行 / 来源</th><th>评分结论</th><th>自动分类与评测异常</th><th v-if="badcases">人工原因</th></tr></thead><tbody><tr v-for="row in rows" :key="`${row.id}-${score}`" :class="{ selected: row.id === caseId }"><td><button class="text-link record-title mono" @click="open(row)">{{ row.case_key }}</button><p class="table-subtext">{{ row.question }}</p></td><td>{{ row.agent_status === 'FAILED' ? '执行失败' : stateNames[row.agent_status || 'PENDING'] || row.agent_status }}<p class="table-subtext">{{ sourceNames[row.source_type] || row.source_type }}</p></td><td>{{ stateNames[row.conclusion || 'UNDETERMINED'] || row.conclusion }}</td><td><div class="tag-list"><ElTag v-for="tag in row.automatic_tags" :key="tag" type="danger" size="small">{{ categoryNames[tag] || tag }}</ElTag><ElTag v-for="item in row.evaluation_issues" :key="item" type="warning" size="small">{{ item }}</ElTag><span v-if="!row.automatic_tags.length && !row.evaluation_issues.length" class="small muted">无失败或异常标签</span></div></td><td v-if="badcases"><div class="tag-list"><ElTag v-for="tag in row.annotation?.manual_tags || []" :key="tag" size="small" type="info">{{ tag }}</ElTag></div><p class="table-subtext">{{ row.annotation?.note || '尚未标记' }}</p><button class="text-link small" @click="open(row)">查看并标记</button></td></tr></tbody></table></div><div v-if="total > 20" class="pagination"><ElPagination :current-page="page" :total="total" :page-size="20" layout="prev, pager, next" @current-change="(value: number) => router.replace({ query: { ...route.query, page: String(value) } })" /></div></AsyncState></section><CaseDetailPanel v-if="caseId" :case-id="caseId" :score-set-id="score" @score-change="scoreChange" @saved="load" /></template>
